<section class="section dashboard-page"><div class="container form-page">
    <div class="page-heading"><div><span class="eyebrow">Refund record</span><h1><?= e($refund['refund_reference']) ?></h1><p class="muted">Razorpay Test Mode</p></div><a class="button button-secondary" href="<?= e(url('admin/refunds')) ?>">All refunds</a></div>
    <?php if ($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?>
