    <div class="panel"><dl class="details-list"><div><dt>Status</dt><dd><span class="status-badge status-<?= e($refund['status']) ?>"><?= e($refund['status']) ?></span></dd></div><div><dt>Booking</dt><dd><a href="<?= e(url('admin/bookings/' . $refund['booking_id'])) ?>"><?= e($refund['booking_reference']) ?></a></dd></div><div><dt>Customer</dt><dd><?= e($refund['customer_name']) ?> &middot; <?= e($refund['customer_email']) ?></dd></div><div><dt>Event</dt><dd><?= e($refund['event_title']) ?></dd></div><div><dt>Refund</dt><dd><?= e(money($refund['amount'])) ?> at <?= e($refund['refund_percentage']) ?>%</dd></div><div><dt>Source</dt><dd><?= e($refund['source']) ?> cancellation</dd></div><div><dt>Attempts</dt><dd><?= e($refund['attempt_count']) ?></dd></div><div><dt>Requested</dt><dd><?= e(local_datetime($refund['requested_at'])) ?></dd></div></dl>
